() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (btn) { btn.click(); return 'Clicked button'; }
  return 'Button not found';
}

() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (btn) {
    btn.scrollIntoView({block: 'center'});
    btn.click();
    return {found: true, visible: btn.offsetParent !== null};
  }
  return {found: false};
}

() => {
  // Check for new windows/tabs that may have been opened
  return {
    windowCount: window.length,
    currentUrl: window.location.href,
    // Check if there's a modal or popup with the full nutrition label
    bodyText: document.body.innerText.includes('Full Nutrition') ? 'has full nutrition text' : 'no full nutrition text',
    // Try to find any opened popup or modal
    popups: window.opener ? 'has opener' : 'no opener',
    // Look for the label data
    iframe: document.querySelectorAll('iframe').length,
    // Check if the click expanded the section
    expandedSection: document.querySelector('.mntl-nutrition-facts-label') ? 'found' : 'not found',
    fullLabelSection: Array.from(document.querySelectorAll('*')).filter(el => el.textContent && el.textContent.includes('% Daily Value')).length
  };
}

() => {
  // Find all buttons that might trigger nutrition expansion
  const buttons = Array.from(document.querySelectorAll('button')).map(b => ({
    text: b.textContent.trim().slice(0, 100),
    aria: b.getAttribute('aria-label') || '',
    id: b.id || ''
  })).filter(b => b.text.toLowerCase().includes('nutrition') || b.text.toLowerCase().includes('label'));

  // Try clicking the "Show Full Nutrition Label" button
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (btn) {
    // Check what happens when clicked - look for event handlers
    const events = [];
    ['click', 'mousedown', 'pointerdown'].forEach(evt => {
      btn.addEventListener(evt, () => events.push(evt), {once: true});
    });
    btn.click();

    // Wait briefly and check for changes
    return new Promise(resolve => {
      setTimeout(() => {
        const labelText = document.body.innerText;
        const hasIron = labelText.match(/Iron[\s\S]{0,30}/);
        const expandedSection = document.querySelector('.mntl-nutrition-facts-label, .nutrition-facts-label, [class*="nutrition-label"]');
        resolve({
          buttonsFound: buttons,
          hasIronText: hasIron ? hasIron[0] : 'Iron not found in body text',
          fullLabelVisible: expandedSection ? expandedSection.outerHTML.slice(0, 500) : 'no full label element',
          bodyHasNutrition: labelText.includes('Show Full') ? 'button still visible' : 'button no longer visible',
          // Also try to find any expanded sections
          fullText: labelText.match(/Total Fat[\s\S]{0,500}/)?.[0] || 'Total Fat not found'
        });
      }, 1000);
    });
  }
  return {buttonsFound: buttons, error: 'Show Full Nutrition Label button not found'};
}

() => {
  // Find the nutrition facts section and scroll to it
  const nutritionSection = document.querySelector('[class*="nutrition"]');
  if (nutritionSection) {
    nutritionSection.scrollIntoView({block: 'center'});
  }

  // Wait briefly for scroll
  return new Promise(resolve => {
    setTimeout(() => {
      const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
      if (btn) {
        const rect = btn.getBoundingClientRect();
        const isVisible = rect.top >= 0 && rect.bottom <= window.innerHeight;
        btn.click();
        resolve({clicked: true, isVisible, buttonRect: {top: rect.top, bottom: rect.bottom}});
      } else {
        resolve({clicked: false, error: 'Button not found'});
      }
    }, 500);
  });
}

() => {
  // Check for any modal/dialog that might be open
  const modals = document.querySelectorAll('[role="dialog"], .modal, [class*="modal"], [class*="dialog"], [class*="overlay"]');
  const visibleModals = Array.from(modals).filter(m => {
    const style = window.getComputedStyle(m);
    return style.display !== 'none' && style.visibility !== 'hidden';
  });

  // Check if there's an opened new tab via window.open
  const allOpenLinks = document.querySelectorAll('a[target="_blank"]');

  // Check the button click - look at the button itself
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');

  return {
    visibleModals: visibleModals.length,
    modalClasses: visibleModals.map(m => m.className).slice(0, 5),
    openLinks: allOpenLinks.length,
    buttonFound: !!btn,
    buttonHTML: btn ? btn.outerHTML.slice(0, 300) : 'not found',
    buttonDataAttrs: btn ? Object.fromEntries(Array.from(btn.attributes).map(a => [a.name, a.value])) : {}
  };
}

() => {
  // Find the button and click it, also wait for any DOM changes
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (!btn) return {error: 'Button not found'};

  // Get current nutrition facts visible
  const beforeText = document.querySelector('.mntl-nutrition-facts-summary, [class*="nutrition-facts"]')?.innerText || '';

  btn.click();

  return new Promise(resolve => {
    setTimeout(() => {
      // Look for any popup, modal, or expanded content
      const allDialogs = document.querySelectorAll('[role="dialog"]');
      const visibleDialogs = Array.from(allDialogs).filter(d => {
        const rect = d.getBoundingClientRect();
        const style = window.getComputedStyle(d);
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
      });

      // Look for full nutrition label
      const fullLabel = document.querySelector('.mntl-nutrition-facts-label, [class*="full-nutrition"]');

      // Get all visible text on page that contains iron or nutrition info
      const pageText = document.body.innerText;
      const ironMatch = pageText.match(/Iron[:\s]+[\d.]+mg/);

      resolve({
        buttonClicked: true,
        visibleDialogs: visibleDialogs.length,
        dialogClasses: visibleDialogs.map(d => d.className).slice(0, 3),
        fullLabelFound: !!fullLabel,
        fullLabelContent: fullLabel?.innerText?.slice(0, 800) || 'no full label',
        ironText: ironMatch ? ironMatch[0] : 'Iron text not found in body',
        pageSnippet: pageText.match(/Iron[\s\S]{0,200}/)?.[0] || 'no iron text'
      });
    }, 1500);
  });
}

() => {
  // Check if a new tab opened with the full nutrition label
  const w = window;
  return {
    href: w.location.href,
    bodyContainsIron: document.body.innerText.toLowerCase().includes('iron'),
    bodySnippet: document.body.innerText.slice(0, 500),
    ironContext: document.body.innerText.match(/Iron[^a-z][\s\S]{0,200}/i)?.[0] || 'no iron'
  };
}

() => {
  return __data("Recipe").map(r => ({
    name: r.name,
    reviewCount: r.aggregateRating?.reviewCount,
    ratingCount: r.aggregateRating?.ratingCount,
    ratingValue: r.aggregateRating?.ratingValue,
    nutrition: r.nutrition,
    recipeYield: r.recipeYield,
    recipeIngredient: r.recipeIngredient
  }));
}

() => {
  const data = __data("Recipe");
  const result = data.map(r => JSON.stringify({
    name: r.name,
    reviewCount: r.aggregateRating?.reviewCount,
    ratingCount: r.aggregateRating?.ratingCount,
    nutrition: r.nutrition
  }));

  // Create a div to display the result
  const div = document.createElement('div');
  div.id = 'script-result';
  div.style.cssText = 'position:fixed;top:0;left:0;width:100%;background:white;z-index:99999;padding:20px;font-size:14px;white-space:pre-wrap;border:2px solid red;';
  div.textContent = result.join('\n\n');
  document.body.appendChild(div);

  return 'added div';
}

() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (btn) {
    btn.scrollIntoView({block: 'center'});
    return {scrolled: true, buttonTop: btn.getBoundingClientRect().top};
  }
  return {scrolled: false};
}

() => {
  // Check for new tabs/windows
  const opener = window.opener;

  // Check for any iframe content
  const iframes = document.querySelectorAll('iframe');
  const iframeSrcs = Array.from(iframes).map(f => f.src);

  // Get all visible buttons on page
  const allButtons = Array.from(document.querySelectorAll('button')).map(b => b.textContent.trim().slice(0, 50));

  // Check for any nutrition label elements
  const labels = document.querySelectorAll('[class*="nutrition"], [class*="label"]');
  const labelTexts = Array.from(labels).slice(0, 5).map(l => l.className + ': ' + l.innerText.slice(0, 100));

  return {
    hasOpener: !!opener,
    iframes: iframeSrcs,
    allButtons: allButtons,
    labels: labelTexts,
    bodyHasIron: document.body.innerText.toLowerCase().includes('iron'),
    ironContext: document.body.innerText.match(/.{0,50}iron.{0,100}/i)?.[0] || 'no iron match'
  };
}

() => {
  // First, get all the data
  const data = __data("Recipe");
  let resultText = '';
  if (data && data.length > 0) {
    resultText = JSON.stringify(data.map(r => ({
      name: r.name,
      reviewCount: r.aggregateRating?.reviewCount,
      ratingCount: r.aggregateRating?.ratingValue,
      nutrition: r.nutrition
    })), null, 2);
  } else {
    resultText = 'No Recipe data found';
  }

  // Also try to get any iron info from the page directly
  const bodyText = document.body.innerText;
  const ironInfo = bodyText.match(/Iron[^a-z][\s\S]{0,200}/i)?.[0] || 'Iron text not found';

  // Create a result div with the info
  const oldDiv = document.getElementById('script-result');
  if (oldDiv) oldDiv.remove();

  const div = document.createElement('div');
  div.id = 'script-result';
  div.style.cssText = 'position:fixed;top:0;left:0;width:100%;background:yellow;color:black;z-index:999999;padding:10px;font-size:12px;white-space:pre-wrap;border:2px solid red;max-height:80vh;overflow:auto;';
  div.textContent = 'DATA: ' + resultText.slice(0, 3000) + '\n\nIRON INFO: ' + ironInfo;
  document.body.appendChild(div);

  return {hasData: data.length > 0, dataPreview: resultText.slice(0, 500), ironInfo};
}

() => {
  // Get current URL
  const url = window.location.href;
  return url;
}

() => {
  const btns = document.querySelectorAll('button');
  const target = Array.from(btns).find(b => b.textContent.trim() === 'Show Full Nutrition Label');
  if (!target) return 'NOT_FOUND';

  // Force the button to be visible and trigger click via multiple methods
  target.style.display = 'block';
  target.style.visibility = 'visible';
  target.scrollIntoView({block: 'center'});

  // Trigger native click
  const event = new MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    view: window,
    button: 0
  });
  target.dispatchEvent(event);
  target.click();

  // Also try with pointer events
  const pointerEvent = new PointerEvent('pointerdown', {bubbles: true, cancelable: true});
  target.dispatchEvent(pointerEvent);
  const pointerEvent2 = new PointerEvent('pointerup', {bubbles: true, cancelable: true});
  target.dispatchEvent(pointerEvent2);

  return 'CLICK_DISPATCHED: ' + target.outerHTML.substring(0, 100);
}

() => {
  const btn = __find('Show Full Nutrition Label', 'button');
  return btn.map(b => ({
    index: b.index,
    text: b.textContent.trim(),
    className: b.className
  }));
}

() => {
  // Look for JSON-LD structured data with nutrition info
  const scripts = document.querySelectorAll('script[type="application/ld+json"]');
  const allData = Array.from(scripts).map(s => s.textContent).join('\n');

  // Try to find nutrition info
  const ironMatch = allData.match(/"ironContent"[^,}]+/);
  const nutritionMatch = allData.match(/"nutrition"[^}]+}/);

  return {
    scriptsCount: scripts.length,
    hasIron: !!ironMatch,
    ironMatch: ironMatch?.[0],
    nutrition: nutritionMatch?.[0]?.slice(0, 1000),
    dataPreview: allData.slice(0, 500)
  };
}

() => {
  const scripts = document.querySelectorAll('script[type="application/ld+json"]');
  const allData = Array.from(scripts).map(s => s.textContent).join('|SEPARATOR|');
  return allData.slice(0, 5000);
}

() => {
  // Find the button by various selectors
  const btns = document.querySelectorAll('button');
  let target = null;
  for (const b of btns) {
    if (b.textContent.trim() === 'Show Full Nutrition Label') {
      target = b;
      break;
    }
  }

  if (!target) return 'Button not found in document';

  // Scroll to it
  target.scrollIntoView({block: 'center'});

  // Get the parent and click
  const rect = target.getBoundingClientRect();
  const computed = window.getComputedStyle(target);

  // Click the button
  target.click();

  return JSON.stringify({
    found: true,
    isVisible: computed.display !== 'none' && computed.visibility !== 'hidden',
    rect: {top: rect.top, left: rect.left, width: rect.width, height: rect.height},
    classes: target.className,
    id: target.id,
    parentClass: target.parentElement?.className
  });
}

() => {
  const matches = __find('Show Full Nutrition Label');
  return matches.map(m => ({
    tag: m.tagName,
    text: m.textContent.trim().slice(0, 100),
    index: m.index,
    className: m.className
  }));
}
